<?php
function padChartForest($rows,$w,$h){
 $label=padChartProcessOption('label','label');$value=padChartProcessOption('value','value');$low=padChartProcessOption('low','low');$high=padChartProcessOption('high','high');$scale=padChartProcessOption('scale','linear');$interval=padChartProcessOption('interval','Supplied interval');
 if(!in_array($scale,['linear','log']))throw new InvalidArgumentException('Forest scale must be linear or log');$reference=padTagParm('reference',$scale==='log'?1:0);if(!padChartFinite($reference)||($scale==='log'&&$reference<=0))throw new InvalidArgumentException('Forest reference is outside scale domain');$reference=(float)$reference;
 $p=[];$v=[$reference];foreach(padChartProcessRows($rows) as $r){foreach([$value,$low,$high] as $field)if(!padChartFinite($r[$field]??NULL)||($scale==='log'&&$r[$field]<=0))throw new InvalidArgumentException('Forest estimates and bounds must be finite and positive for log scale');if($r[$low]>$r[$value]||$r[$value]>$r[$high])throw new InvalidArgumentException('Forest requires low <= value <= high');$p[]=[padChartText($r,$label),(float)$r[$value],(float)$r[$low],(float)$r[$high]];array_push($v,(float)$r[$low],(float)$r[$high]);}if(!$p)return '';if(count($p)>60)throw new InvalidArgumentException('Forest supports at most 60 rows');
 $transform=$scale==='log'?fn($n)=>log($n):fn($n)=>$n;$lo=$transform(min($v));$hi=$transform(max($v));if($lo===$hi){$delta=$scale==='log'?1:max(1,abs($lo)*.1);$lo-=$delta;$hi+=$delta;}if(!is_finite($hi-$lo)||($scale==='log'&&(!is_finite(exp($hi))||exp($lo)<=0)))throw new InvalidArgumentException('Forest numeric range is too large');$x=fn($n)=>160+($transform($n)-$lo)/($hi-$lo)*($w-180);$h=max($h,50+24*count($p));$y=fn($i)=>25+($i+.5)*($h-65)/count($p);
 $desc=array_map(fn($r)=>$r[0].': '.padChartNumber($r[1]).', '.$interval.' '.padChartNumber($r[2]).' to '.padChartNumber($r[3]),$p);array_unshift($desc,'Reference '.padChartNumber($reference).', '.$scale.' scale');[$id,$svg]=padChartOpen('forest',$p,$desc,padChartProcessOption('title','Forest plot'),$w,$h);
 $svg.='<path class="pc-axis" stroke-dasharray="4 3" d="M'.padChartXY($x($reference)).' 20V'.($h-40).'"/>';
 for($i=0;$i<=4;$i++){$t=$lo+($hi-$lo)*($i/4);$n=$scale==='log'?exp($t):$t;$xx=padChartXY($x($n));$svg.='<text x="'.$xx.'" y="'.($h-15).'" text-anchor="middle">'.padChartNumber($n).'</text>';}
 foreach($p as $i=>$r){$yy=padChartXY($y($i));$a=padChartXY($x($r[2]));$b=padChartXY($x($r[3]));$svg.='<g class="pc-mark"><title>'.padChartAttr($desc[$i+1]).'</title><text x="150" y="'.padChartXY($y($i)+4).'" text-anchor="end">'.padChartAttr(padChartFit($r[0],145)).'</text><path class="pc-l1" fill="none" d="M'.$a.' '.$yy.'H'.$b.'M'.$a.' '.padChartXY($y($i)-5).'V'.padChartXY($y($i)+5).'M'.$b.' '.padChartXY($y($i)-5).'V'.padChartXY($y($i)+5).'"/><circle class="pc-c1 pc-ring" cx="'.padChartXY($x($r[1])).'" cy="'.$yy.'" r="4"/></g>';}
 return $svg.'</svg>';
}
